#!/usr/bin/env node
/**
 * qlint reference CLI — static lint (Stage 1) plus inspect/run (Stage 2).
 *
 * Deliberately small: argument parsing, file I/O, schema loading, and
 * rendering. Checking logic lives in lint-suite.ts / static-checks.ts,
 * planning in plan.ts, projection in projection.ts, replay in replay.ts.
 * Exit codes follow docs/design-v0.1.md; see USAGE.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { pathToFileURL } from "node:url";
import { parseBackendCapabilities } from "./capabilities.js";
import type {
  BackendCapabilities,
  ExecutionPlan,
  Json,
  QuestionSuite,
  RecordedResponse,
  RunReport,
  ScreeningPack,
  ScreeningRequest,
  ScreeningReport,
} from "./contracts.js";
import type { LintReport } from "./lint-suite.js";
import { InternalLintError, LINT_SCOPE, lintSuiteSource } from "./lint-suite.js";
import { buildScreeningRequests, screenFromRecordings, screenLive, ScreeningError } from "./screening.js";
import { buildPlan, PlanError, planDigest } from "./plan.js";
import type { ReplayCase } from "./replay.js";
import { ReplayError, replayPlan, runReportDigest } from "./replay.js";
import type { SchemaValidators } from "./schema-validation.js";
import { createSchemaValidators, loadSchemaSync } from "./schema-validation.js";
import { createHttpTransport } from "./transport.js";

export const USAGE = `qlint — question contract checker (reference implementation)

Usage:
  qlint lint <suite.json> [--capabilities <caps.json>] [--format text|json]
  qlint inspect <suite.json> [--out <plan.json>] [--format text|json]
                 [--max-requests N] [--max-bytes N] [--max-tokens N] [--allow-restricted]
  qlint run <plan.json> --cases <cases.jsonl> --replay <recorded.jsonl>
             [--out <report.json>] [--format text|json]
  qlint screen <suite.json> (--replay <recorded.jsonl> | --dry-run
                             | --allow-provider typesafe --max-requests N)
              [--out <report.json>] [--record <recorded.jsonl>] [--timeout-seconds N]
              [--format text|json] [--fail-on-signal]
  qlint --help
  qlint --version

Exit codes:
  0  every check the command performs completed and found no violations
  1  the input violated the suite contract or the JSON Schema
  2  usage, I/O, plan, or tool-configuration failure (including digest mismatch)
  3  run could not complete for lack of recorded evidence (results left not_run)

lint runs JSON Schema validation and cross-reference checks only.
Semantic screening, dataset probes, metamorphic tests, fuzzing, and calibration
are NOT run; the report lists them under "not run" and never presents a clean
static lint as semantic approval.
inspect writes a digest-bound execution plan; it never contacts a provider.
run executes a plan against recorded responses only; live providers are not
implemented in this bundle.
screen asks the semantic screening meta-questions over recorded Jev responses
or, with --allow-provider typesafe, over the live endpoint. Live mode reads
TYPESAFE_CREDENTIAL_ENV from the environment (the key is never printed or stored),
requires an explicit --max-requests budget, and records backend failures as
backend_error observations rather than question defects. Signals are
model_signal diagnostics; without --fail-on-signal they do not fail the command.`;

export interface CliStreams {
  stdout(text: string): void;
  stderr(text: string): void;
}

class CliError extends Error {}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function readVersion(): string {
  try {
    const parsed: unknown = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8"));
    if (typeof parsed === "object" && parsed !== null && typeof (parsed as { version?: unknown }).version === "string") {
      return (parsed as { version: string }).version;
    }
  } catch {
    // The version is informative, not a check.
  }
  return "0.0.0";
}

function loadCatalogRuleIds(): string[] {
  const parsed: unknown = JSON.parse(readFileSync(new URL("../rules/catalog.json", import.meta.url), "utf8"));
  if (typeof parsed !== "object" || parsed === null) throw new CliError("rules/catalog.json is not a JSON object");
  const rules = (parsed as { rules?: unknown }).rules;
  if (!Array.isArray(rules)) throw new CliError("rules/catalog.json has no rules array");
  const ids: string[] = [];
  for (const rule of rules) {
    const id = typeof rule === "object" && rule !== null ? (rule as { id?: unknown }).id : undefined;
    if (typeof id !== "string") throw new CliError("rules/catalog.json contains a rule without a string id");
    ids.push(id);
  }
  return ids;
}

function loadValidators(): SchemaValidators {
  return createSchemaValidators({
    suite: loadSchemaSync(new URL("../schemas/question-suite.schema.json", import.meta.url)),
    diagnostic: loadSchemaSync(new URL("../schemas/diagnostic.schema.json", import.meta.url)),
    executionPlan: loadSchemaSync(new URL("../schemas/execution-plan.schema.json", import.meta.url)),
  });
}

const VALUE_FLAGS = new Set([
  "--out", "--format", "--capabilities", "--max-requests", "--max-bytes", "--max-tokens",
  "--cases", "--replay", "--allow-provider", "--timeout-seconds", "--record",
]);
const BOOLEAN_FLAGS = new Set(["--help", "-h", "--version", "-v", "--allow-restricted", "--dry-run", "--fail-on-signal"]);

interface ParsedArgv {
  flags: Map<string, string>;
  booleans: Set<string>;
  positionals: string[];
}

type Command =
  | { kind: "help" }
  | { kind: "version" }
  | { kind: "lint"; file: string; capabilitiesPath?: string; format: "text" | "json" }
  | {
      kind: "inspect";
      file: string;
      out?: string;
      format: "text" | "json";
      maxRequests?: number;
      maxBytes?: number;
      maxTokens?: number;
      allowRestricted: boolean;
    }
  | { kind: "run"; planPath: string; casesPath: string; replayPath: string; out?: string; format: "text" | "json" }
  | {
      kind: "screen";
      file: string;
      replayPath?: string;
      out?: string;
      format: "text" | "json";
      dryRun: boolean;
      failOnSignal: boolean;
      allowProvider?: "typesafe";
      maxRequests?: number;
      timeoutSeconds?: number;
      recordPath?: string;
    }
  | { kind: "error"; message: string };

function parseArgv(argv: string[]): ParsedArgv | { error: string } {
  const flags = new Map<string, string>();
  const booleans = new Set<string>();
  const positionals: string[] = [];
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index]!;
    if (BOOLEAN_FLAGS.has(arg)) {
      booleans.add(arg);
      continue;
    }
    if (VALUE_FLAGS.has(arg)) {
      const value = argv[index + 1];
      if (value === undefined || value.startsWith("--")) return { error: `${arg} requires a value` };
      flags.set(arg, value);
      index += 1;
      continue;
    }
    if (arg.startsWith("-")) return { error: `unknown option: ${arg}` };
    positionals.push(arg);
  }
  return { flags, booleans, positionals };
}

function checkFlags(parsed: ParsedArgv, allowedFlags: string[], allowedBooleans: string[]): string | undefined {
  for (const flag of parsed.flags.keys()) {
    if (!allowedFlags.includes(flag)) return `${flag} is not valid for ${parsed.positionals[0] ?? "this command"}`;
  }
  for (const flag of parsed.booleans) {
    if (flag === "--help" || flag === "-h" || flag === "--version" || flag === "-v") continue;
    if (!allowedBooleans.includes(flag)) return `${flag} is not valid for ${parsed.positionals[0] ?? "this command"}`;
  }
  return undefined;
}

function parseFormat(parsed: ParsedArgv): "text" | "json" | string {
  const value = parsed.flags.get("--format");
  if (value === undefined) return "text";
  if (value !== "text" && value !== "json") return '--format must be "text" or "json"';
  return value;
}

function positiveInteger(parsed: ParsedArgv, flag: string): number | undefined | string {
  const value = parsed.flags.get(flag);
  if (value === undefined) return undefined;
  if (!/^[1-9]\d*$/.test(value)) return `${flag} must be a positive integer`;
  return Number(value);
}

function parseArgs(argv: string[]): Command {
  const parsed = parseArgv(argv);
  if ("error" in parsed) return { kind: "error", message: parsed.error };
  if (parsed.booleans.has("--help") || parsed.booleans.has("-h")) return { kind: "help" };
  if (parsed.booleans.has("--version") || parsed.booleans.has("-v")) return { kind: "version" };

  const [commandName, file, extra] = parsed.positionals;
  if (commandName === undefined) return { kind: "error", message: "missing command" };
  if (file === undefined) return { kind: "error", message: `${commandName} requires a file path` };
  if (extra !== undefined) return { kind: "error", message: `unexpected argument: ${extra}` };

  if (commandName === "lint") {
    const flagError = checkFlags(parsed, ["--format", "--capabilities"], []);
    if (flagError) return { kind: "error", message: flagError };
    const format = parseFormat(parsed);
    if (format !== "text" && format !== "json") return { kind: "error", message: format };
    const capabilitiesPath = parsed.flags.get("--capabilities");
    return { kind: "lint", file, ...(capabilitiesPath === undefined ? {} : { capabilitiesPath }), format };
  }

  if (commandName === "inspect") {
    const flagError = checkFlags(parsed, ["--out", "--format", "--max-requests", "--max-bytes", "--max-tokens"], ["--allow-restricted"]);
    if (flagError) return { kind: "error", message: flagError };
    const format = parseFormat(parsed);
    if (format !== "text" && format !== "json") return { kind: "error", message: format };
    const maxRequests = positiveInteger(parsed, "--max-requests");
    const maxBytes = positiveInteger(parsed, "--max-bytes");
    const maxTokens = positiveInteger(parsed, "--max-tokens");
    for (const value of [maxRequests, maxBytes, maxTokens]) {
      if (typeof value === "string") return { kind: "error", message: value };
    }
    const out = parsed.flags.get("--out");
    return {
      kind: "inspect",
      file,
      format,
      allowRestricted: parsed.booleans.has("--allow-restricted"),
      ...(out === undefined ? {} : { out }),
      ...(typeof maxRequests === "number" ? { maxRequests } : {}),
      ...(typeof maxBytes === "number" ? { maxBytes } : {}),
      ...(typeof maxTokens === "number" ? { maxTokens } : {}),
    };
  }

  if (commandName === "run") {
    const flagError = checkFlags(parsed, ["--out", "--format", "--cases", "--replay", "--allow-provider"], []);
    if (flagError) return { kind: "error", message: flagError };
    if (parsed.flags.has("--allow-provider")) {
      return { kind: "error", message: "live providers are not implemented in this bundle; use --replay <recorded.jsonl>" };
    }
    const format = parseFormat(parsed);
    if (format !== "text" && format !== "json") return { kind: "error", message: format };
    const casesPath = parsed.flags.get("--cases");
    const replayPath = parsed.flags.get("--replay");
    if (casesPath === undefined) return { kind: "error", message: "run requires --cases <cases.jsonl>" };
    if (replayPath === undefined) return { kind: "error", message: "run requires --replay <recorded.jsonl>" };
    const out = parsed.flags.get("--out");
    return { kind: "run", planPath: file, casesPath, replayPath, format, ...(out === undefined ? {} : { out }) };
  }

  if (commandName === "screen") {
    const flagError = checkFlags(
      parsed,
      ["--out", "--format", "--replay", "--max-requests", "--timeout-seconds", "--record", "--allow-provider"],
      ["--dry-run", "--fail-on-signal"],
    );
    if (flagError) return { kind: "error", message: flagError };
    const format = parseFormat(parsed);
    if (format !== "text" && format !== "json") return { kind: "error", message: format };
    const replayPath = parsed.flags.get("--replay");
    const dryRun = parsed.booleans.has("--dry-run");
    const providerFlag = parsed.flags.get("--allow-provider");
    if (providerFlag !== undefined && providerFlag !== "typesafe") {
      return { kind: "error", message: `unsupported provider: ${providerFlag} (only "typesafe")` };
    }
    if (providerFlag !== undefined && replayPath !== undefined) {
      return { kind: "error", message: "--allow-provider and --replay are mutually exclusive" };
    }
    const maxRequests = positiveInteger(parsed, "--max-requests");
    const timeoutSeconds = positiveInteger(parsed, "--timeout-seconds");
    for (const value of [maxRequests, timeoutSeconds]) {
      if (typeof value === "string") return { kind: "error", message: value };
    }
    if (providerFlag !== undefined && !dryRun && typeof maxRequests !== "number") {
      return { kind: "error", message: "live screening requires an explicit --max-requests budget" };
    }
    if (replayPath === undefined && providerFlag === undefined && !dryRun) {
      return { kind: "error", message: "screen requires --replay <recorded.jsonl>, --allow-provider typesafe, or --dry-run" };
    }
    const out = parsed.flags.get("--out");
    const recordPath = parsed.flags.get("--record");
    return {
      kind: "screen",
      file,
      format,
      dryRun,
      failOnSignal: parsed.booleans.has("--fail-on-signal"),
      ...(replayPath === undefined ? {} : { replayPath }),
      ...(out === undefined ? {} : { out }),
      ...(providerFlag === undefined ? {} : { allowProvider: "typesafe" as const }),
      ...(typeof maxRequests === "number" ? { maxRequests } : {}),
      ...(typeof timeoutSeconds === "number" ? { timeoutSeconds } : {}),
      ...(recordPath === undefined ? {} : { recordPath }),
    };
  }

  return { kind: "error", message: `unknown command: ${commandName}` };
}

function readText(path: string | URL, what: string): string {
  try {
    return readFileSync(path, "utf8");
  } catch (error) {
    throw new CliError(`cannot read ${what} ${String(path)}: ${errorMessage(error)}`);
  }
}

function readJson(path: string | URL, what: string): unknown {
  const source = readText(path, what);
  try {
    return JSON.parse(source);
  } catch (error) {
    throw new CliError(`${what} ${String(path)} is not valid JSON: ${errorMessage(error)}`);
  }
}

function loadScreeningPack(): ScreeningPack {
  const parsed = readJson(new URL("../rules/screening-pack.json", import.meta.url), "screening pack");
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    throw new CliError("rules/screening-pack.json is not a JSON object");
  }
  const pack = parsed as ScreeningPack;
  if (!Array.isArray(pack.rules) || pack.rules.length === 0) {
    throw new CliError("rules/screening-pack.json has no rules");
  }
  for (const rule of pack.rules) {
    const complete = typeof rule.id === "string"
      && typeof rule.summary === "string"
      && typeof rule.message === "string"
      && typeof rule.applicability?.instructions === "string"
      && typeof rule.sufficiency?.instructions === "string"
      && typeof rule.violation?.instructions === "string";
    if (!complete) throw new CliError(`rules/screening-pack.json rule ${String(rule.id)} is incomplete`);
  }
  return pack;
}

function readCapabilities(path: string): BackendCapabilities {
  const parsed = readJson(path, "capabilities file");
  try {
    return parseBackendCapabilities(parsed);
  } catch (error) {
    throw new CliError(`capabilities file ${path}: ${errorMessage(error)}`);
  }
}

function parseJsonLines(source: string, what: string, parseLine: (value: unknown, line: number) => void): void {
  source.split("\n").forEach((line, index) => {
    const trimmed = line.trim();
    if (trimmed === "") return;
    let parsed: unknown;
    try {
      parsed = JSON.parse(trimmed);
    } catch (error) {
      throw new CliError(`${what} line ${index + 1} is not valid JSON: ${errorMessage(error)}`);
    }
    parseLine(parsed, index + 1);
  });
}

function readCases(path: string): ReplayCase[] {
  const cases: ReplayCase[] = [];
  parseJsonLines(readText(path, "cases file"), "cases file", (value, line) => {
    if (typeof value !== "object" || value === null || Array.isArray(value)) {
      throw new CliError(`cases file line ${line} must be a JSON object`);
    }
    const record = value as Record<string, unknown>;
    if (typeof record.caseId !== "string" || record.caseId === "") {
      throw new CliError(`cases file line ${line} needs a non-empty string caseId`);
    }
    if (!("state" in record)) throw new CliError(`cases file line ${line} needs a state value`);
    cases.push({ caseId: record.caseId, state: record.state as Json });
  });
  if (cases.length === 0) throw new CliError("cases file contains no cases");
  return cases;
}

function readRecordings(path: string): RecordedResponse[] {
  const recordings: RecordedResponse[] = [];
  parseJsonLines(readText(path, "recorded responses file"), "recorded responses file", (value, line) => {
    if (typeof value !== "object" || value === null || Array.isArray(value)) {
      throw new CliError(`recorded responses file line ${line} must be a JSON object`);
    }
    const record = value as Record<string, unknown>;
    if (typeof record.requestDigest !== "string" || !/^sha256:[0-9a-f]{64}$/.test(record.requestDigest)) {
      throw new CliError(`recorded responses file line ${line} needs a sha256 requestDigest`);
    }
    if (!("response" in record)) throw new CliError(`recorded responses file line ${line} needs a response`);
    recordings.push({ requestDigest: record.requestDigest, response: record.response as Json });
  });
  return recordings;
}

function renderLintText(report: LintReport): string {
  const lines: string[] = [];
  lines.push(`qlint ${report.version} — ${LINT_SCOPE} (schema + cross-reference checks; no network)`);
  if (report.file !== null) lines.push(`file: ${report.file}`);
  if (report.suiteId !== null) {
    const versionSuffix = report.schemaVersion === null ? "" : ` (schemaVersion ${report.schemaVersion})`;
    lines.push(`suite: ${report.suiteId}${versionSuffix}`);
  }
  const { errors, warnings, infos } = report.summary;
  lines.push(
    errors === 0 && warnings === 0 && infos === 0
      ? "result: no violations in the checks that ran"
      : `result: ${errors} error(s), ${warnings} warning(s), ${infos} info`,
  );
  for (const diagnostic of report.diagnostics) {
    const location = diagnostic.locations[0];
    const place = location?.line === undefined
      ? report.file ?? "<input>"
      : `${location.file ?? report.file ?? "<input>"}:${location.line}:${location.column ?? 1}`;
    lines.push(`${place}  ${diagnostic.severity}  ${diagnostic.ruleId}  ${location?.pointer ?? "/"}`);
    lines.push(`    ${diagnostic.message}`);
  }
  const count = (status: string): number => report.coverage.filter(entry => entry.status === status).length;
  lines.push(`coverage: ${count("passed")} passed, ${count("flagged")} flagged, ${count("not_run")} not run (${report.coverage.length} catalog rules)`);
  for (const item of report.notExecuted) lines.push(`not run: ${item}`);
  lines.push(`note: ${report.note}`);
  return lines.join("\n") + "\n";
}

function renderPlanText(plan: ExecutionPlan, outPath: string | undefined): string {
  const lines: string[] = [];
  lines.push(`qlint ${plan.tool.version} — execution plan (provider: ${plan.provider.name}; network: ${plan.provider.network ? "yes" : "no"})`);
  lines.push(`suite: ${plan.suite.id} (${plan.suite.digest})`);
  lines.push(`requests: ${plan.requestCount} (maxRequests ${plan.maxRequests})`);
  lines.push(`redaction: ${plan.questions[0]?.redaction.policy ?? "explicit-projection-v0.1"}`);
  for (const question of plan.questions) {
    lines.push(`  ${question.questionId} @ ${question.atStage} [${question.profile}, ${question.mode}, ${question.outputKind}]`);
    lines.push(`    inputs: ${question.inputs.map(field => field.fieldId).join(", ") || "(none)"}`);
    lines.push(`    policyRefs: ${question.policyRefs.map(field => field.fieldId).join(", ") || "(none)"}`);
    lines.push(`    excluded: ${question.redaction.excludedFieldIds.join(", ") || "(none)"}`);
    lines.push(`    restricted: ${question.redaction.restrictedFieldIds.join(", ") || "none"}`);
    lines.push(`    limits: ${question.limits.rationale}`);
  }
  for (const note of plan.notes) lines.push(`note: ${note}`);
  lines.push(`plan digest: ${plan.digest}`);
  if (outPath !== undefined) lines.push(`written: ${outPath}`);
  return lines.join("\n") + "\n";
}

function renderRunText(report: RunReport): string {
  const lines: string[] = [];
  lines.push(`qlint ${report.tool.version} — run (mode: ${report.mode}; provider: replay; network: no)`);
  lines.push(`plan: ${report.planDigest}`);
  lines.push(`suite: ${report.suite.id} (${report.suite.digest})`);
  lines.push(`cases: ${report.summary.cases}, questions: ${report.summary.questions}`);
  lines.push(`results: ${report.summary.replayed} replayed, ${report.summary.abstained} abstained, ${report.summary.invalid} invalid, ${report.summary.notRun} not run`);
  for (const result of report.results) {
    if (result.status === "replayed") continue;
    lines.push(`  ${result.caseId} ${result.questionId} ${result.status}${result.reason === undefined ? "" : `: ${result.reason}`}`);
  }
  for (const item of report.notExecuted) lines.push(`not run: ${item}`);
  lines.push(`report digest: ${report.digest}`);
  return lines.join("\n") + "\n";
}

function exitCodeForRun(report: RunReport): number {
  if (report.summary.invalid > 0) return 1;
  if (report.summary.notRun > 0) return 3;
  return 0;
}

function renderScreeningRequestsText(requests: ScreeningRequest[]): string {
  const lines: string[] = [];
  lines.push("qlint — semantic screening requests (dry run; nothing is sent)");
  lines.push(`requests: ${requests.length} (one per question)`);
  for (const request of requests) {
    lines.push(`  ${request.questionId}: ${request.rules.map(rule => rule.ruleId).join(", ")}`);
    lines.push(`    digest: ${request.requestDigest}`);
  }
  lines.push("note: thresholds are uncalibrated reference defaults and are recorded in the screening report.");
  lines.push("note: state contains the question text and field descriptors only; no field values, labels, or expected diagnostics.");
  return lines.join("\n") + "\n";
}

function renderScreeningText(report: ScreeningReport): string {
  const lines: string[] = [];
  lines.push(`qlint ${report.tool.version} — screening (provider: ${report.provider}${report.model === undefined ? "" : `, model: ${report.model}`}; network: ${report.provider === "typesafe" ? "yes" : "no"})`);
  lines.push(`suite: ${report.suite.id} (${report.suite.digest})`);
  lines.push(`policy: ${report.policy.policyId} (applicability>=${report.policy.applicabilityAtLeast}, sufficiency>=${report.policy.sufficiencyAtLeast}, signal>=${report.policy.signalAtLeast})`);
  if (report.usage !== undefined) {
    lines.push(`usage: ${report.usage.requests} requests, ${report.usage.inputTokens} input tokens, ${report.usage.outputTokens} output tokens, ${report.usage.latencyMs} ms`);
  }
  lines.push(`requests: ${report.summary.requests}`);
  lines.push(`observations: ${report.summary.signals} signals, ${report.summary.inconclusive} inconclusive, ${report.summary.notRun} not run, ${report.summary.malformed} malformed, ${report.summary.backendErrors} backend errors`);
  for (const observation of report.observations) {
    if (observation.status === "no_signal") continue;
    const probabilities = [
      observation.applicability === undefined ? undefined : `a=${observation.applicability}`,
      observation.sufficiency === undefined ? undefined : `s=${observation.sufficiency}`,
      observation.violation === undefined ? undefined : `v=${observation.violation}`,
    ].filter((value): value is string => value !== undefined).join(" ");
    lines.push(`  ${observation.questionId} ${observation.ruleId} ${observation.status}${probabilities === "" ? "" : ` (${probabilities})`}`);
  }
  for (const diagnostic of report.diagnostics) {
    const location = diagnostic.locations[0];
    lines.push(`  ${report.suite.id}${location?.pointer ?? "/"}  warning  ${diagnostic.ruleId}  ${diagnostic.message}`);
  }
  for (const item of report.notExecuted) lines.push(`not run: ${item}`);
  lines.push(`report digest: ${report.digest}`);
  return lines.join("\n") + "\n";
}

function exitCodeForScreening(report: ScreeningReport, failOnSignal: boolean): number {
  if (report.summary.backendErrors > 0) return 2;
  if (report.summary.malformed > 0) return 2;
  if (failOnSignal && report.diagnostics.length > 0) return 1;
  if (report.summary.notRun > 0) return 3;
  return 0;
}

export async function run(argv: string[], streams: CliStreams): Promise<number> {
  const command = parseArgs(argv);
  if (command.kind === "help") {
    streams.stdout(USAGE + "\n");
    return 0;
  }
  if (command.kind === "version") {
    streams.stdout(readVersion() + "\n");
    return 0;
  }
  if (command.kind === "error") {
    streams.stderr(`qlint: ${command.message}\n\n${USAGE}\n`);
    return 2;
  }

  try {
    if (command.kind === "lint") {
      const capabilities = command.capabilitiesPath === undefined ? undefined : readCapabilities(command.capabilitiesPath);
      const source = readText(command.file, "suite file");
      const report = lintSuiteSource({
        source,
        file: command.file,
        ...(capabilities === undefined ? {} : { capabilities }),
        catalogRuleIds: loadCatalogRuleIds(),
        validators: loadValidators(),
        version: readVersion(),
      });
      streams.stdout(command.format === "json" ? JSON.stringify(report, null, 2) + "\n" : renderLintText(report));
      return report.summary.errors > 0 ? 1 : 0;
    }

    if (command.kind === "inspect") {
      const validators = loadValidators();
      const source = readText(command.file, "suite file");
      const lint = lintSuiteSource({
        source,
        file: command.file,
        catalogRuleIds: loadCatalogRuleIds(),
        validators,
        version: readVersion(),
      });
      if (lint.summary.errors > 0) {
        streams.stdout(command.format === "json" ? JSON.stringify(lint, null, 2) + "\n" : renderLintText(lint));
        return 1;
      }
      const plan = buildPlan(JSON.parse(source) as QuestionSuite, {
        version: readVersion(),
        ...(command.maxRequests === undefined ? {} : { maxRequests: command.maxRequests }),
        ...(command.maxBytes === undefined ? {} : { maxBytes: command.maxBytes }),
        ...(command.maxTokens === undefined ? {} : { maxTokens: command.maxTokens }),
        ...(command.allowRestricted ? { allowRestricted: true } : {}),
      });
      const issues = validators.executionPlan(plan);
      if (issues.length > 0) {
        throw new InternalLintError(`generated plan does not satisfy schemas/execution-plan.schema.json: ${issues.map(issue => issue.message).join("; ")}`);
      }
      if (command.out !== undefined) {
        writeFileSync(command.out, JSON.stringify(plan, null, 2) + "\n");
      }
      streams.stdout(command.format === "json" ? JSON.stringify(plan, null, 2) + "\n" : renderPlanText(plan, command.out));
      return 0;
    }

    if (command.kind === "screen") {
      const validators = loadValidators();
      const source = readText(command.file, "suite file");
      const lint = lintSuiteSource({
        source,
        file: command.file,
        catalogRuleIds: loadCatalogRuleIds(),
        validators,
        version: readVersion(),
      });
      if (lint.summary.errors > 0) {
        streams.stdout(command.format === "json" ? JSON.stringify(lint, null, 2) + "\n" : renderLintText(lint));
        return 1;
      }
      const suite = JSON.parse(source) as QuestionSuite;
      const pack = loadScreeningPack();
      if (command.dryRun) {
        const requests = buildScreeningRequests(suite, pack);
        streams.stdout(command.format === "json"
          ? JSON.stringify({ provider: "replay", requests }, null, 2) + "\n"
          : renderScreeningRequestsText(requests));
        return 0;
      }
      let report: ScreeningReport;
      if (command.allowProvider === "typesafe") {
        const providerCredential = process.env.TYPESAFE_CREDENTIAL_ENV;
        if (providerCredential === undefined || providerCredential === "") {
          throw new CliError("TYPESAFE_CREDENTIAL_ENV is not set; qlint never prints or stores the key");
        }
        const transport = createHttpTransport({
          providerCredential,
          timeoutMs: (command.timeoutSeconds ?? 30) * 1000,
        });
        const recordings: RecordedResponse[] = [];
        const outcome = await screenLive(suite, pack, transport, readVersion(), {
          ...(command.maxRequests === undefined ? {} : { maxRequests: command.maxRequests }),
          onRecord: recording => recordings.push(recording),
        });
        if (command.recordPath !== undefined) {
          const body = recordings.map(recording => JSON.stringify(recording)).join("\n");
          writeFileSync(command.recordPath, recordings.length === 0 ? "" : `${body}\n`, { mode: 0o600 });
        }
        if (outcome.failures.length > 0) {
          streams.stderr(`qlint: ${outcome.failures.length} backend failure(s); first: ${outcome.failures[0]!.failure.message}\n`);
        }
        report = outcome.report;
      } else {
        if (command.replayPath === undefined) throw new CliError("screen requires --replay <recorded.jsonl>");
        const recordings = readRecordings(command.replayPath);
        report = screenFromRecordings(suite, pack, recordings, readVersion());
      }
      for (const diagnostic of report.diagnostics) {
        const issues = validators.diagnostic(diagnostic);
        if (issues.length > 0) {
          throw new InternalLintError(`emitted diagnostic ${diagnostic.ruleId} does not satisfy schemas/diagnostic.schema.json: ${issues.map(issue => issue.message).join("; ")}`);
        }
      }
      if (command.out !== undefined) {
        writeFileSync(command.out, JSON.stringify(report, null, 2) + "\n");
      }
      streams.stdout(command.format === "json" ? JSON.stringify(report, null, 2) + "\n" : renderScreeningText(report));
      return exitCodeForScreening(report, command.failOnSignal);
    }

    // command.kind === "run"
    const validators = loadValidators();
    const plan = readJson(command.planPath, "plan file") as ExecutionPlan;
    const planIssues = validators.executionPlan(plan);
    if (planIssues.length > 0) {
      throw new CliError(`plan ${command.planPath} is not a valid execution plan: ${planIssues.map(issue => `${issue.pointer} ${issue.message}`).join("; ")}`);
    }
    if (plan.digest !== planDigest(plan)) {
      throw new CliError(`plan digest mismatch: file has ${plan.digest}, content computes ${planDigest(plan)}`);
    }
    const cases = readCases(command.casesPath);
    const recordings = readRecordings(command.replayPath);
    const report = replayPlan(plan, cases, recordings, readVersion());
    if (report.digest !== runReportDigest(report)) {
      throw new InternalLintError("replay report digest does not match its content");
    }
    if (command.out !== undefined) {
      writeFileSync(command.out, JSON.stringify(report, null, 2) + "\n");
    }
    streams.stdout(command.format === "json" ? JSON.stringify(report, null, 2) + "\n" : renderRunText(report));
    return exitCodeForRun(report);
  } catch (error) {
    if (error instanceof CliError || error instanceof InternalLintError || error instanceof PlanError
        || error instanceof ReplayError || error instanceof ScreeningError) {
      streams.stderr(`qlint: ${errorMessage(error)}\n`);
      return 2;
    }
    streams.stderr(`qlint: unexpected failure: ${errorMessage(error)}\n`);
    return 2;
  }
}

const invokedPath = process.argv[1];
if (invokedPath !== undefined && import.meta.url === pathToFileURL(invokedPath).href) {
  void run(process.argv.slice(2), {
    stdout: text => process.stdout.write(text),
    stderr: text => process.stderr.write(text),
  }).then(code => {
    process.exitCode = code;
  });
}

state.run_corpus_mjs:
/**
 * Runs the screening evaluation corpus and computes the section-4 metrics:
 * per-rule precision/recall/unknown, legitimate-stop rate, evidence-span
 * correctness, usage, latency, and execution failures. Metrics are reported
 * overall and separately for the tuning and eval splits.
 *
 * Usage:
 *   node evaluation/run-corpus.mjs --live [--model jev-latest] [--record evaluation/recorded-live.jsonl]
 *   node evaluation/run-corpus.mjs --replay evaluation/recorded-live.jsonl [--out evaluation/results.json]
 *
 * Live mode reads TYPESAFE_CREDENTIAL_ENV from the environment and sends one request
 * per case (the corpus is 60 cases). Nothing is retried automatically.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { parseArgs } from "node:util";
import { buildScreeningRequests, screenFromRecordings, screenLive } from "../dist/screening.js";
import { createHttpTransport } from "../dist/transport.js";
import { loadCases, validateCases } from "./validate-cases.mjs";

const root = new URL("../", import.meta.url);
const pack = JSON.parse(readFileSync(new URL("rules/screening-pack.json", root), "utf8"));
const version = JSON.parse(readFileSync(new URL("package.json", root), "utf8")).version;

const { values } = parseArgs({
  options: {
    live: { type: "boolean", default: false },
    replay: { type: "string" },
    out: { type: "string", default: "evaluation/results.json" },
    record: { type: "string", default: "evaluation/recorded-live.jsonl" },
    model: { type: "string" },
    split: { type: "string", default: "all" },
  },
});

if (!["all", "tuning", "eval"].includes(values.split)) {
  console.error("--split must be all, tuning, or eval");
  process.exit(2);
}

const allCases = loadCases();
const problems = validateCases(allCases);
if (problems.length > 0) {
  for (const problem of problems) console.error(`case validation: ${problem}`);
  process.exit(2);
}
const cases = values.split === "all" ? allCases : allCases.filter(item => item.split === values.split);

const classifyCase = (item, report) => {
  const diagnostics = report.diagnostics;
  const observation = ruleId => report.observations.find(entry => entry.ruleId === ruleId);
  if (item.kind === "legitimate") {
    const stopped = diagnostics.length > 0;
    return {
      caseId: item.caseId,
      family: item.family,
      split: item.split,
      outcome: stopped ? "stopped" : "clean",
      signalRules: diagnostics.map(diagnostic => diagnostic.ruleId),
      unknownRules: report.observations
        .filter(entry => ["inconclusive", "not_applicable", "not_run", "malformed", "backend_error"].includes(entry.status))
        .map(entry => entry.ruleId),
    };
  }
  const expected = new Set([...item.expected.rules, ...item.expected.alternatives]);
  const hits = diagnostics.filter(diagnostic => expected.has(diagnostic.ruleId));
  if (hits.length > 0) {
    const spanOk = hits.some(diagnostic => diagnostic.locations[0]?.pointer === item.expected.evidencePointer);
    return {
      caseId: item.caseId,
      family: item.family,
      split: item.split,
      outcome: "hit",
      signalRules: diagnostics.map(diagnostic => diagnostic.ruleId),
      spanOk,
    };
  }
  const expectedObservations = item.expected.rules.map(observation).filter(entry => entry !== undefined);
  const unknown = expectedObservations.some(entry => ["inconclusive", "not_applicable", "not_run", "malformed", "backend_error"].includes(entry.status));
  return {
    caseId: item.caseId,
    family: item.family,
    split: item.split,
    outcome: unknown ? "unknown" : "miss",
    signalRules: diagnostics.map(diagnostic => diagnostic.ruleId),
  };
};

const metric = subset => {
  const rules = ["QSM001", "QSM002", "QSM003", "QSM004", "QBE004"];
  const perRule = Object.fromEntries(rules.map(rule => [rule, { tp: 0, fn: 0, unknown: 0, fp: 0 }]));
  let stoppedLegitimate = 0;
  let legitimate = 0;
  let hits = 0;
  let spanOk = 0;
  for (const item of subset) {
    const diagnostics = item.report.diagnostics;
    if (item.kind === "legitimate") {
      legitimate += 1;
      if (diagnostics.length > 0) stoppedLegitimate += 1;
      for (const diagnostic of diagnostics) {
        if (perRule[diagnostic.ruleId]) perRule[diagnostic.ruleId].fp += 1;
      }
      continue;
    }
    const expected = new Set([...item.expected.rules, ...item.expected.alternatives]);
    const hit = diagnostics.filter(diagnostic => expected.has(diagnostic.ruleId));
    const outcome = item.outcome;
    for (const rule of item.expected.rules) {
      if (!perRule[rule]) continue;
      if (outcome === "hit") perRule[rule].tp += 1;
      else if (outcome === "unknown") perRule[rule].unknown += 1;
      else perRule[rule].fn += 1;
    }
    for (const diagnostic of diagnostics) {
      if (expected.has(diagnostic.ruleId)) continue;
      if (perRule[diagnostic.ruleId]) perRule[diagnostic.ruleId].fp += 1;
    }
    if (hit.length > 0) {
      hits += 1;
      if (hit.some(diagnostic => diagnostic.locations[0]?.pointer === item.expected.evidencePointer)) spanOk += 1;
    }
  }
  return {
    perRule,
    legitimateStopRate: legitimate === 0 ? null : stoppedLegitimate / legitimate,
    evidenceSpanCorrectness: hits === 0 ? null : spanOk / hits,
    defectHits: subset.filter(item => item.kind === "defect" && item.outcome === "hit").length,
    defectUnknown: subset.filter(item => item.kind === "defect" && item.outcome === "unknown").length,
    defectMisses: subset.filter(item => item.kind === "defect" && item.outcome === "miss").length,
  };
};

const run = async () => {
  const detailed = [];
  let usage = null;
  let failures = 0;

  if (values.live) {
    const providerCredential = process.env.TYPESAFE_CREDENTIAL_ENV;
    if (providerCredential === undefined || providerCredential === "") {
      console.error("live mode requires TYPESAFE_CREDENTIAL_ENV in the environment (the key is never written to disk)");
      process.exit(2);
    }
    const transport = createHttpTransport({ providerCredential });
    const recordings = [];
    usage = { requests: 0, inputTokens: 0, outputTokens: 0, latencyMs: 0 };
    for (const item of cases) {
      const outcome = await screenLive(item.suite, pack, transport, version, {
        maxRequests: 1,
        ...(values.model === undefined ? {} : { model: values.model }),
        onRecord: recording => recordings.push(recording),
      });
      failures += outcome.failures.length;
      if (outcome.report.usage) {
        usage.requests += outcome.report.usage.requests;
        usage.inputTokens += outcome.report.usage.inputTokens;
        usage.outputTokens += outcome.report.usage.outputTokens;
        usage.latencyMs += outcome.report.usage.latencyMs;
      }
      detailed.push({ ...item, report: outcome.report, ...classifyCase(item, outcome.report) });
    }
    writeFileSync(values.record, recordings.map(recording => JSON.stringify(recording)).join("\n") + (recordings.length === 0 ? "" : "\n"), { mode: 0o600 });
  } else {
    if (values.replay === undefined) {
      console.error("usage: node evaluation/run-corpus.mjs --live | --replay <recorded.jsonl>");
      process.exit(2);
    }
    const byDigest = new Map();
    for (const line of readFileSync(values.replay, "utf8").split("\n")) {
      if (line.trim() === "") continue;
      const recording = JSON.parse(line);
      byDigest.set(recording.requestDigest, recording);
    }
    for (const item of cases) {
      const requests = buildScreeningRequests(item.suite, pack);
      const recordingsForCase = requests
        .map(request => byDigest.get(request.requestDigest))
        .filter(recording => recording !== undefined);
      const report = screenFromRecordings(item.suite, pack, recordingsForCase, version);
      detailed.push({ ...item, report, ...classifyCase(item, report) });
    }
  }

  const subset = split => detailed.filter(item => item.split === split);
  const metrics = {
    corpus: {
      total: detailed.length,
      defect: detailed.filter(item => item.kind === "defect").length,
      legitimate: detailed.filter(item => item.kind === "legitimate").length,
    },
    overall: metric(detailed),
    tuning: metric(subset("tuning")),
    eval: metric(subset("eval")),
  };
  const result = {
    mode: values.live ? "live" : "replay",
    model: values.model ?? pack.model ?? "jev-latest",
    policy: detailed[0]?.report.policy ?? null,
    metrics,
    usage,
    backendFailures: failures,
    cases: detailed.map(item => ({
      caseId: item.caseId,
      family: item.family,
      kind: item.kind,
      split: item.split,
      outcome: item.outcome,
      signalRules: item.signalRules,
      spanOk: item.spanOk ?? null,
      diagnostics: item.report.diagnostics.length,
    })),
  };
  writeFileSync(values.out, JSON.stringify(result, null, 2) + "\n");

  const print = (label, value) => {
    console.log(`${label}: hits ${value.defectHits}, unknown ${value.defectUnknown}, misses ${value.defectMisses}, legitimate-stop ${value.legitimateStopRate === null ? "n/a" : `${Math.round(value.legitimateStopRate * 100)}%`}, span ${value.evidenceSpanCorrectness === null ? "n/a" : `${Math.round(value.evidenceSpanCorrectness * 100)}%`}`);
    for (const [rule, counts] of Object.entries(value.perRule)) {
      console.log(`  ${rule}: tp ${counts.tp}, unknown ${counts.unknown}, fn ${counts.fn}, fp ${counts.fp}`);
    }
  };
  console.log(`screening corpus (${values.live ? "live" : "replay"}), model ${result.model}`);
  if (usage) console.log(`usage: ${usage.requests} requests, ${usage.inputTokens} input tokens, ${usage.outputTokens} output tokens, ${usage.latencyMs} ms, failures ${failures}`);
  print("overall", metrics.overall);
  print("tuning", metrics.tuning);
  print("eval", metrics.eval);
  console.log(`wrote ${values.out}`);
};

await run();

state.validate_cases_mjs:
/**
 * Validates the evaluation corpus offline:
 * counts, splits, unique ids, lint-clean suites, and that the expected rule
 * actually applies to the case's question. No model calls.
 *
 * Exported as validateCases() for tests; also runnable directly.
 */
import { readFileSync } from "node:fs";
import { pathToFileURL } from "node:url";
import { createSchemaValidators, loadSchemaSync } from "../dist/schema-validation.js";
import { lintSuiteSource } from "../dist/lint-suite.js";
import { ruleApplies } from "../dist/screening.js";

const root = new URL("../", import.meta.url);
const validators = createSchemaValidators({
  suite: loadSchemaSync(new URL("schemas/question-suite.schema.json", root)),
  diagnostic: loadSchemaSync(new URL("schemas/diagnostic.schema.json", root)),
  executionPlan: loadSchemaSync(new URL("schemas/execution-plan.schema.json", root)),
});
const catalog = JSON.parse(readFileSync(new URL("rules/catalog.json", root), "utf8"));
const pack = JSON.parse(readFileSync(new URL("rules/screening-pack.json", root), "utf8"));
const familyRule = new Map(pack.rules.map(rule => [rule.id, rule]));

export function validateCases(cases) {
  const problems = [];
  const check = (condition, message) => {
    if (!condition) problems.push(message);
  };

  check(cases.length === 60, `expected 60 cases, found ${cases.length}`);
  const defect = cases.filter(item => item.kind === "defect");
  const legitimate = cases.filter(item => item.kind === "legitimate");
  check(defect.length === 40, `expected 40 defect cases, found ${defect.length}`);
  check(legitimate.length === 20, `expected 20 legitimate cases, found ${legitimate.length}`);
  check(cases.filter(item => item.split === "tuning").length === 30, "expected 30 tuning cases");
  check(cases.filter(item => item.split === "eval").length === 30, "expected 30 eval cases");

  const ids = new Set();
  for (const item of cases) {
    check(typeof item.caseId === "string" && item.caseId !== "", "caseId must be a non-empty string");
    check(!ids.has(item.caseId), `duplicate caseId ${item.caseId}`);
    ids.add(item.caseId);
    check(["ja", "en"].includes(item.language), `${item.caseId}: language must be ja or en`);
    check(["tuning", "eval"].includes(item.split), `${item.caseId}: split must be tuning or eval`);
    check(["QSM001", "QSM002", "QSM003", "QSM004", "QBE004"].includes(item.family), `${item.caseId}: unknown family ${item.family}`);
    check(typeof item.groupId === "string" && item.groupId !== "", `${item.caseId}: groupId is required`);

    if (item.kind === "defect") {
      check(item.expected.status === "signal", `${item.caseId}: defect expects signal`);
      check(Array.isArray(item.expected.rules) && item.expected.rules.includes(item.family), `${item.caseId}: expected rules must name the family`);
      check(/^\/questions\/0\/(instructions|output)$/.test(item.expected.evidencePointer), `${item.caseId}: evidencePointer must target instructions or output`);
      const rule = familyRule.get(item.family);
      check(rule !== undefined, `${item.caseId}: family has no screening rule`);
      if (rule) check(ruleApplies(rule, item.suite.questions[0]), `${item.caseId}: expected rule ${item.family} does not apply to this question`);
    } else {
      check(item.expected.status === "no_signal", `${item.caseId}: legitimate expects no_signal`);
      check(item.expected.rules.length === 0, `${item.caseId}: legitimate expects no rules`);
    }

    const source = JSON.stringify(item.suite);
    const lint = lintSuiteSource({
      source,
      file: `${item.caseId}.json`,
      catalogRuleIds: catalog.rules.map(rule => rule.id),
      validators,
      version: "corpus-check",
    });
    check(lint.summary.errors === 0, `${item.caseId}: suite has lint errors: ${lint.diagnostics.map(d => d.message).join("; ")}`);
  }
  return problems;
}

export function loadCases() {
  const text = readFileSync(new URL("cases.jsonl", import.meta.url), "utf8");
  return text.split("\n").filter(line => line.trim() !== "").map(line => JSON.parse(line));
}

const isMain = process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href;
if (isMain) {
  const problems = validateCases(loadCases());
  if (problems.length > 0) {
    for (const problem of problems) console.error(`case validation: ${problem}`);
    process.exitCode = 1;
  } else {
    console.log("evaluation corpus: 60 cases valid (40 defect / 20 legitimate, 30 tuning / 30 eval)");
  }
}

state.case_definitions_mjs:
/**
 * Screening evaluation corpus definitions (implementation plan section 4).
 *
 * 60 cases: 40 defect cases (5 implemented rule families x 8) and 20
 * look-alike legitimate cases (4 per family). Defect texts are human-authored
 * per family; legitimate cases cover explicit AND conditions, crisp numeric or
 * negative-side boundaries, predict-as-declared questions, self-contained
 * ordinal levels, overlapping best_fit categories, and rare-event detectors.
 *
 * Splits: 30 tuning / 30 eval. Thresholds may be studied on the tuning split
 * only; the eval split is reported untouched.
 *
 * Run `node evaluation/generate-cases.mjs` to write evaluation/cases.jsonl.
 */

const BOOL = (trueText, falseText) => ({ kind: "boolean", criteria: { true: trueText, false: falseText } });
const ORD = (axis, levels) => ({ kind: "ordinal", axis, levels: levels.map((description, index) => ({ id: `level_${index}`, description })) });
const CAT = (selection, options) => ({ kind: "categorical", selection, options: options.map((description, index) => ({ id: `option_${index}`, description })) });

function suiteFor({ id, mode = "interpret", instructions, applicability, evidenceBoundary, output, prediction, policyRefs = [], inputs = ["task", "diff"] }) {
  return {
    schemaVersion: "0.1",
    id,
    state: {
      id: `state_${id}`,
      stages: [{ id: "start", after: [] }, { id: "complete", after: ["start"] }],
      fields: [
        { id: "task", pointer: "/task", valueType: "string", nullable: false, availableFrom: "start", role: "evidence", derivedFrom: [], sensitivity: "internal" },
        { id: "diff", pointer: "/diff", valueType: "string", nullable: false, availableFrom: "start", role: "evidence", derivedFrom: [], sensitivity: "internal" },
        { id: "outcome", pointer: "/outcome", valueType: "string", nullable: false, availableFrom: "complete", role: "target", derivedFrom: [], sensitivity: "internal" },
        ...policyRefs.map(fieldId => ({ id: fieldId, pointer: `/${fieldId}`, valueType: "string", nullable: false, availableFrom: "start", role: "policy", derivedFrom: [], sensitivity: "internal" })),
      ],
    },
    questions: [{
      id: "q1",
      revision: 1,
      mode,
      instructions,
      inputs,
      policyRefs,
      applicability: applicability ?? "対象の作業が存在する。",
      evidenceBoundary: evidenceBoundary ?? "提示された入力だけを根拠にする。",
      missingInput: "abstain",
      insufficientEvidence: "abstain",
      ...(prediction === undefined ? {} : { prediction }),
      output,
    }],
    bindings: [{ questionId: "q1", atStage: "start", profile: "feature", gates: [], onIndeterminate: "abstain" }],
  };
}

const cases = [];
const counters = new Map();
const nextId = (family, kind, language) => {
  const key = `${family}_${kind}_${language}`;
  const count = (counters.get(key) ?? 0) + 1;
  counters.set(key, count);
  return `${family.toLowerCase()}_${kind}_${language}_${String(count).padStart(2, "0")}`;
};

function defect(family, group, language, split, question, rationale, extra = {}) {
  const caseId = nextId(family, "defect", language);
  cases.push({
    caseId,
    groupId: `${family}_${group}`,
    family,
    kind: "defect",
    language,
    split,
    suite: suiteFor({ id: caseId, ...question }),
    expected: {
      status: "signal",
      rules: [family],
      alternatives: extra.alternatives ?? [],
      evidencePointer: extra.evidencePointer ?? "/questions/0/instructions",
      rationale,
    },
  });
}

function legit(family, group, language, split, question, rationale) {
  const caseId = nextId(family, "legit", language);
  cases.push({
    caseId,
    groupId: `${family}_${group}`,
    family,
    kind: "legitimate",
    language,
    split,
    suite: suiteFor({ id: caseId, ...question }),
    expected: {
      status: "no_signal",
      rules: [],
      alternatives: [],
      evidencePointer: "/questions/0/instructions",
      rationale,
    },
  });
}

// --- QSM001 compound-judgment ------------------------------------------------

defect("QSM001", "state_outcome", "ja", "tuning",
